const w=k=>words[lang][k]||words.en[k]||k,loc=x=>typeof x==='object'?(x[lang]||x.en):x;
const el=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;};
function link(text,url){const a=el('a',text);a.href=url;if(/^https?:/.test(url)){a.target='_blank';a.rel='noopener noreferrer';}return a;}
function badge(status){return el('span',w(status),'visit-badge '+status);}
function sourceLinks(ids){const p=el('p',undefined,'visit-small');p.append(w('sources')+' · ');ids.forEach((id,i)=>{const s=guide.sources.find(s=>s.id===id);if(!s)return;if(i)p.append(' · ');p.append(link(s.publisher,s.url));});return p;}
function atMap(id){const b=el('button',w('onMap'));b.type='button';b.addEventListener('click',()=>{if(!visiblePlaces().some(p=>p.id===id)){$('#place-filter').value='all';renderMarkers();}selectPlace(id,true);$('#field-map').scrollIntoView({behavior:'smooth'});});return b;}
function walking(p){return 'https://www.google.com/maps/dir/?api=1&destination='+encodeURIComponent(p.address)+'&travelmode=walking';}
let pointsLayer,observationsLayer,recordsLayer,streetLayer,markers={};
function visiblePlaces(){const f=$('#place-filter').value;return guide.places.filter(p=>f==='all'||f==='core'&&p.order||f==='event'&&p.type==='event'||f==='contact'&&(p.type==='contact'||p.type==='hub'));}
function pinIcon(p){return L.divIcon({className:'',html:'<span aria-hidden="true" class="visit-pin '+p.status+(p.id===selected?' selected':'')+'">'+p.number+'</span>',iconSize:[34,34],iconAnchor:[17,17]});}
function renderMarkers(){if(!map)return;pointsLayer.clearLayers();markers={};const visible=visiblePlaces();for(const p of visible){const m=L.marker([p.coordinates[1],p.coordinates[0]],{icon:pinIcon(p),title:p.number+' · '+loc(p.name),keyboard:true,alt:p.number+' · '+loc(p.name)}).addTo(pointsLayer);m.on('click',()=>selectPlace(p.id));m.bindTooltip(p.number+' · '+loc(p.name),{direction:'top',offset:[0,-18]});markers[p.id]=m;}const list=$('#location-list');list.replaceChildren();visible.forEach(p=>{const b=el('button',p.number+' · '+loc(p.name));b.type='button';b.setAttribute('aria-pressed',String(p.id===selected));b.addEventListener('click',()=>selectPlace(p.id,true));list.append(b);});}
function selectPlace(id,pan=false){const p=guide.places.find(p=>p.id===id);if(!p)return;selected=id;renderMarkers();if(pan)map.setView([p.coordinates[1],p.coordinates[0]],17);const box=$('#place-detail');box.replaceChildren(el('p',p.number+' / '+w(p.status),'visit-kicker'),el('h3',loc(p.name)),badge(p.status),el('p',loc(p.task)));if(p.time)box.append(el('p',p.time+' · JST','visit-small'));const dl=el('dl');for(const [term,definition]of [[w('address'),p.address],[w('scope'),w(p.in_wider_area?'inside':'outside')],[w('position'),p.geocode_result?w('positionNote'):w('anchorNote')]]){dl.append(el('dt',term),el('dd',definition));}box.append(dl,sourceLinks(p.sources));const actions=el('div',undefined,'visit-toolbar');const note=el('button',w('noteHere'));note.type='button';note.addEventListener('click',()=>{setRecordPlace(p.id);$('#field-records').scrollIntoView({behavior:'smooth'});});actions.append(note,link(w('walkLink'),walking(p)));box.append(actions);const detail=el('details');detail.append(el('summary',w('method')),el('p',p.location_method,'visit-small'),link(w('read'),p.location_source));box.append(detail);const related=el('div',undefined,'visit-related');related.append(el('h4',w('related')));guide.contacts.filter(c=>c.place===p.id).forEach(c=>related.append(link(c.name,'#contact-'+c.id)));guide.activities.forEach((a,i)=>{if(a.place===p.id)related.append(link(loc(a.title)+' · '+w(a.status),'#activity-'+i));});if(related.childElementCount>1)box.append(related);}
function renderLegend(){const box=$('#map-legend');box.replaceChildren();for(const key of ['boundary','streetLine','pastStreet','observation','observe','unconfirmed','past','appointment','sunday']){const span=el('span'),swatch=el('i',undefined,'visit-key '+(key==='streetLine'?'street':key));swatch.setAttribute('aria-hidden','true');span.append(swatch,w(key));box.append(span);}}
function renderGuide(){document.documentElement.lang=lang;document.title=w('title')+' / Kajicho';$$('[data-v]').forEach(e=>e.textContent=w(e.dataset.v));$('#community-map').setAttribute('aria-label',w('mapAria'));renderLegend();if(!guide)return;
 const route=$('#route-list');route.replaceChildren();guide.places.filter(p=>p.order).forEach(p=>{const li=el('li');li.append(el('b',p.number),el('h3',loc(p.name)),el('small',p.time+' · JST'),el('p',loc(p.task)),atMap(p.id));route.append(li);});
 const contacts=$('#contact-list');contacts.replaceChildren();guide.contacts.forEach(c=>{const card=el('article',undefined,'visit-card');card.id='contact-'+c.id;card.append(el('p',String(c.priority).padStart(2,'0'),'visit-kicker'),el('h3',c.name),el('p',loc(c.why)));if(c.contact_detail)card.append(el('p',c.contact_detail));const question=el('details');question.append(el('summary',w('question')));for(const l of ['zh','ja']){const p=el('p',c.ask[l],'visit-card-ask');p.lang=l;question.append(p);}card.append(question);const links=el('div',undefined,'visit-card-links');links.append(atMap(c.place),link(w('contact'),c.contact_url));card.append(links,sourceLinks(c.sources));contacts.append(card);});
 const activity=$('#activity-list');activity.replaceChildren();guide.activities.forEach((a,i)=>{const card=el('article',undefined,'visit-card');card.id='activity-'+i;card.append(badge(a.status),el('h3',loc(a.title)),el('p',a.date,'visit-small'),el('p',loc(a.summary)),atMap(a.place),sourceLinks(a.sources));activity.append(card);});
 const optional=$('#optional-list');optional.replaceChildren();guide.places.filter(p=>p.type==='event').forEach(p=>{const card=el('article',undefined,'visit-card');card.append(badge(p.status),el('h3',loc(p.name)),el('p',p.time+' · JST'),el('p',loc(p.task)),atMap(p.id),sourceLinks(p.sources));optional.append(card);});
 const questions=$('#question-list');questions.replaceChildren();guide.questions.forEach((q,i)=>{const item=el('article',undefined,'visit-question');item.append(el('h3',String(i+1).padStart(2,'0')+' / '+loc(q.topic)));const pair=el('div',undefined,'visit-language-pair');for(const l of ['zh','ja']){const col=el('div');col.lang=l;col.append(el('b',l==='zh'?'中文':'日本語'),el('p',q[l]));pair.append(col);}item.append(pair);questions.append(item);});
 const sources=$('#source-list');sources.replaceChildren();guide.sources.forEach(s=>{const li=el('li');li.id='source-'+s.id;li.append(link(s.title,s.url),el('small',s.publisher+' · '+s.kind.replaceAll('_',' ')),el('small',(s.published_on?w('published')+' '+s.published_on:w('notDated'))+' · '+w('checkedLabel')+' '+s.checked_on));if(s.activity_dates)li.append(el('small',w('eventDates')+' · '+s.activity_dates.join(' / ')));if(s.data_year)li.append(el('small',w('dataYear')+' · '+s.data_year));sources.append(li);});
 const select=$('#record-place'),value=select.value;select.replaceChildren();for(const p of guide.places){const o=el('option',p.number+' · '+loc(p.name));o.value=p.id;select.append(o);}const other=el('option',w('custom'));other.value='custom';select.append(other);select.value=value||selected;
 renderMarkers();selectPlace(selected);renderRecords();
}
function initMap(context,boundary,streets,pastEvent){map=L.map('community-map',{scrollWheelZoom:false,zoomControl:true}).setView([35.69225,139.7720],17);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap contributors</a>',opacity:.6}).addTo(map);
 L.geoJSON(context,{interactive:false,style:f=>{const k=f.properties.layer;return k==='osm_buildings'?{weight:.4,color:'#cec9bf',fillColor:'#ded9cd',fillOpacity:.3}:k==='rail'?{weight:1,color:'#687173',opacity:.7}:k==='water'?{weight:0,fillColor:'#a0c4cc',fillOpacity:.6}:{weight:1,color:'#aaa89e',opacity:.7};}}).addTo(map);
 L.geoJSON(boundary,{interactive:false,style:{color:'#59457f',weight:2.5,dashArray:'7 5',fill:false}}).addTo(map);
 streetLayer=L.geoJSON(streets,{style:{color:'#246d69',weight:5,opacity:.7}}).addTo(map);streetLayer.eachLayer(layer=>{const name=layer.feature.properties.name;if(name)layer.bindTooltip(name,{sticky:true});});
 L.geoJSON(pastEvent,{style:{color:'#786c5c',weight:6,dashArray:'6 5',opacity:.85}}).addTo(map);
 pointsLayer=L.layerGroup().addTo(map);observationsLayer=L.layerGroup().addTo(map);recordsLayer=L.layerGroup().addTo(map);map.on('click',e=>{if(!placing)return;customLocation={coordinates:[e.latlng.lng,e.latlng.lat],basis:'manual'};placing=false;$('#pick-location').setAttribute('aria-pressed','false');$('#map-status').textContent=w('picked');$('#record-place').value='custom';form.elements.coordinates.value=customLocation.coordinates.map(n=>n.toFixed(6)).join(', ');renderObservationPin(customLocation.coordinates);});
 $('#fit-core').addEventListener('click',()=>fitPlaces('core'));$('#fit-all').addEventListener('click',()=>fitPlaces('all'));$('#place-filter').addEventListener('change',()=>{renderMarkers();const ps=visiblePlaces();if(ps.length){map.fitBounds(ps.map(p=>[p.coordinates[1],p.coordinates[0]]),{padding:[45,45],maxZoom:17});selectPlace(ps[0].id);}});
 $('#pick-location').addEventListener('click',()=>{placing=!placing;$('#pick-location').setAttribute('aria-pressed',String(placing));$('#map-status').textContent=placing?w('pickHint'):'';});fitPlaces('core');
}
function fitPlaces(kind){$('#place-filter').value='all';renderMarkers();const ps=kind==='core'?guide.places.filter(p=>p.order||p.id==='awa-venue'):guide.places;map.fitBounds(ps.map(p=>[p.coordinates[1],p.coordinates[0]]),{padding:[45,45],maxZoom:17});}
const form=$('#field-form');
function renderObservationPin(c){observationsLayer.clearLayers();if(c)L.circleMarker([c[1],c[0]],{radius:9,color:'#1c2022',weight:3,fillColor:'#fff',fillOpacity:1}).addTo(observationsLayer);}
function setRecordPlace(id){form.elements.place.value=id;const p=guide.places.find(p=>p.id===id);customLocation=p?{coordinates:p.coordinates,basis:'reference'}:null;form.elements.coordinates.value=p?p.coordinates.map(n=>n.toFixed(6)).join(', '):'';if(map)renderObservationPin(p?.coordinates);}
function newNote(){form.reset();form.elements.id.value='';setRecordPlace(selected);$('#record-status').textContent='';}
function validRecord(r){return r&&typeof r.id==='string'&&typeof r.date==='string'&&typeof r.facts==='string'&&(!r.location||Array.isArray(r.location.coordinates)&&r.location.coordinates.length===2&&r.location.coordinates.every(Number.isFinite));}
function readRecords(){try{const raw=JSON.parse(localStorage.getItem(RECORD_KEY)||'[]');records=Array.isArray(raw)?raw.filter(validRecord):[];}catch{records=[];$('#record-status').textContent=w('storageError');}}
const labels={date:'date',time:'time',observer:'observer',role:'role',weather:'weather',facts:'facts',account:'account',activity:'activity',meaning:'meaning',photos:'photos',permission:'permission',next:'next'};
function recordText(r){const p=guide.places.find(p=>p.id===r.place);const lines=['FIELD NOTE / '+r.id,w('stop')+': '+(p?loc(p.name):w('custom')),w('coords')+': '+(r.location?r.location.coordinates.map(n=>n.toFixed(6)).join(', '):w('noLocation')),w('method')+': '+w(!r.location?'noLocation':r.location.basis==='manual'?'manual':'reference')];for(const[k,l]of Object.entries(labels)){if(r[k]){const permissionLabels={'public-observation':'publicObservation','notes-only':'notesOnly','photo-agreed':'photoAgreed','audio-agreed':'audioAgreed','all-agreed':'allAgreed','declined':'declined'};const value=k==='role'?w(r[k]):k==='permission'?w(permissionLabels[r[k]]||r[k]):r[k];lines.push(w(l)+': '+value);}}if(p)lines.push('Place sources: '+p.sources.map(id=>guide.sources.find(s=>s.id===id)?.url).filter(Boolean).join(' | '));return lines.join('\n');}
function persist(nextRecords){try{localStorage.setItem(RECORD_KEY,JSON.stringify(nextRecords));records=nextRecords;return true;}catch{$('#record-status').textContent=w('storageError');return false;}}
function renderRecords(){if(recordsLayer){recordsLayer.clearLayers();for(const r of records.filter(r=>r.location)){const c=r.location.coordinates;const marker=L.circleMarker([c[1],c[0]],{radius:7,color:'#36353a',weight:2,fillColor:'#fff',fillOpacity:1}).addTo(recordsLayer);marker.bindTooltip(r.date+' '+r.time+' · '+r.facts.slice(0,50));marker.on('click',()=>document.getElementById('note-'+r.id)?.scrollIntoView({behavior:'smooth'}));}}const box=$('#saved-records');box.replaceChildren(el('h3',w('savedTitle')));if(!records.length){box.append(el('p',w('empty'),'visit-small'));return;}for(const r of records){const item=el('article',undefined,'visit-saved-record');item.id='note-'+r.id;item.append(el('pre',recordText(r)));const actions=el('div',undefined,'visit-toolbar'),edit=el('button',w('edit')),del=el('button',deletePending===r.id?w('confirmDelete'):w('remove'));edit.type=del.type='button';edit.addEventListener('click',()=>{for(const k of ['id','place',...Object.keys(labels)])if(form.elements[k])form.elements[k].value=r[k]||'';customLocation=r.location||null;form.elements.coordinates.value=r.location?r.location.coordinates.map(n=>n.toFixed(6)).join(', '):'';if(map)renderObservationPin(r.location?.coordinates);form.scrollIntoView({behavior:'smooth'});});del.addEventListener('click',()=>{if(deletePending!==r.id){deletePending=r.id;renderRecords();return;}if(persist(records.filter(x=>x.id!==r.id))){deletePending=null;renderRecords();$('#record-status').textContent=w('deleted');}});actions.append(edit,del);item.append(actions);box.append(item);}}
form.addEventListener('submit',e=>{e.preventDefault();if(!guide||!form.reportValidity())return;const r=Object.fromEntries(new FormData(form));if(r.permission==='declined'&&r.account.trim()){$('#record-status').textContent=w('declinedError');return;}r.id=r.id||crypto.randomUUID();r.timezone='Asia/Tokyo';r.location=customLocation?{coordinates:[...customLocation.coordinates],basis:customLocation.basis}:null;r.updated_at=new Date().toISOString();if(persist([...records.filter(x=>x.id!==r.id),r])){form.elements.id.value=r.id;$('#record-status').textContent=w('recordSaved');renderRecords();}});
$('#record-place').addEventListener('change',e=>setRecordPlace(e.target.value));
$('#new-record').addEventListener('click',newNote);$('#print-sheet').addEventListener('click',()=>{document.querySelector('.visit-print-table').open=true;window.print();});
$('#copy-records').addEventListener('click',async()=>{if(!records.length){$('#record-status').textContent=w('noCopy');return;}const text=records.map(recordText).join('\n\n---\n\n');try{await navigator.clipboard.writeText(text);$('#record-status').textContent=w('copyDone');}catch{const fallback=$('#copy-fallback');fallback.hidden=false;fallback.value=text;fallback.focus();fallback.select();$('#record-status').textContent=w('copyFallback');}});
$$('.site-languages [data-lang]').forEach(b=>b.addEventListener('click',()=>{lang=b.dataset.lang;try{localStorage.setItem(LANG_KEY,lang);}catch{}renderGuide();}));
async function json(path){const r=await fetch(path);if(!r.ok)throw new Error('Failed '+path);return r.json();}
renderGuide();
try{const [data,context,boundary,streets,pastEvent]=await Promise.all(['fieldwork/guide.json','fieldwork/context.geojson','fieldwork/boundary.geojson','fieldwork/streets.geojson','fieldwork/past-event-street.geojson'].map(json));guide=data;readRecords();if(window.L)initMap(context,boundary,streets,pastEvent);renderGuide();setRecordPlace('station');}catch(e){$('#map-status').textContent=w('loadError');console.error('Field guide load failed',e);}
